import sys,re
lines=[l.rstrip('\n') for l in sys.stdin.read().split('\n')]
# find gutter width from a source line like '  2 │ ' or ' 2 │ '
gw=None
for l in lines:
    m=re.match(r'^(\s*│|\s*\d+ │)',l)
    if m and not l.strip().startswith('╭'):
        pass
