    if re.match(r'^\s+\d+ │',l):
        gw=l.index('│')
        src=l[gw+1:]
        print(f"source line: {src!r}")
        print("cols:", {i+1:c for i,c in enumerate(src)})
for l in lines:
    for i,c in enumerate(l):
        if i>=gw and c in '│╰╭─':
            print(f"   col={i-gw} char={c!r}")
EOF
NO_COLOR=1 /workspace/executable /workspace/example.nix | python3 an2.py"}

