{"command": "cd /tmp/t && cat > an3.py <<'EOF'
import sys,re
lines=[l.rstrip('\n') for l in sys.stdin.read().split('\n')]
src=None
for l in lines:
    if l.strip().startswith('╭'):
        gw=len(l.split('[')[0]); print(l); continue
    m=re.match(r'^\s+\d+ │',l)
    if m:
        gw=l.index('│')
        src=l[gw+1:]
        print(f"SRC {src!r} gutter_width={gw}")
        continue
    marks=[(i-gw,c) for i,c in enumerate(l) if i>=gw and c in '│╰╭─']
    if marks and src is not None:
        s="".join(('%d'%((i%10)) if i==gw else ' ') for i in range(len(l)))
        print("   ", "".join(c if c in '│╰╭─' else ' ' for c in l))
        print("   ", repr(l[gw:]))
        # positions
        d={}
        for col,c in marks: d.setdefault(col,[]).append(c)
        print("    marks:", d)
        rng=[]
        for col,c in marks:
            if c in '╰': rng.append(('start',col))
        print("    span:", marks[0][0], "->", marks[-1][0])
EOF
NO_COLOR=1 /workspace/executable /workspace/example.nix | python3 an3.py"}

