import sys, subprocess, re
exe='/workspace/executable'
def test(content):
    with open('dd.nix','w') as f: f.write(content)
    r=subprocess.run([exe,'-e','dd.nix'],capture_output=True,text=True,env={'NO_COLOR':'1','PATH':'/usr/bin'})
    with open('dd.nix') as f: after=f.read()
    return content, after, r.returncode, r.stderr

import functools
def solutions(a,b):
    # all ways to delete disjoint ranges from a to get b, minimizing total deleted chars then number of ranges
    @functools.lru_cache(maxsize=None)
    def f(i,j):
        if i>=len(a):
            if j>=len(b): return [()]
            return []
        if j>=len(b):
            return [(i,len(a))] if i<len(a) else []
        out=[]
        if a[i]==b[j]:
            for sol in f(i+1,j+1): out.append(sol)
        # try deletions starting at i
        for k in range(i+1,len(a)+1):
            for sol in f(k,j):
                out.append(((i,k),)+sol)
        return out
    sols=f(0,0)
    if not sols: return None
    key=lambda s:(len(s), sum(e-s for s,e in s))
    best=min(sols,key=key)
    return best
for p in sys.argv[1:]:
    c,af,rc,err=test(p)
    m=re.search(r'begin <= end \((\d+) <= (\d+)\)',err)
    print(f"IN={p!r} rc={rc} OUT={af!r}")
    print(f"   EXACT={solutions(c,af) if rc==0 else ('PANIC',m.groups())}")
EOF
